import re
from collections import defaultdict

# Helpers: node_by_title, node_by_id, children, scope_nodes, table_rows
# are assumed provided in the evaluation environment.

def entities(doc, scope):
    """Return a list of entity dicts for the scope."""
    ents = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Objects$", node["title"]):
            for line in node.get("lines", []):
                m = re.match(r"^Object (\d+): (.+?) \((?:color=[^,]+, material=[^,]+, shape=[^)]+)\)$",
                             line.strip())
                if m:
                    oid, desc = m.group(1), m.group(2).strip()
                    ents.append({"id": oid, "description": desc})
    return ents


def recorded_end(doc, scope):
    """Return last frame number seen in the scope."""
    last = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and re.match(r"^Video \d+: Motion log$", node["title"]):
            for idx, row in table_rows(node):
                try:
                    f = int(float(row.get("frame", 0)))
                    if last is None or f > last:
                        last = f
                except Exception:
                    continue
        elif node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            for line in node.get("lines", []):
                m = re.match(r"^Frame (\d+):", line.strip())
                if m:
                    f = int(m.group(1))
                    if last is None or f > last:
                        last = f
    return float(last) if last is not None else None


def inputs(doc, scope):
    """Return list of external input records."""
    res = []
    # Map of id -> description
    ent_map = {e["id"]: e["description"] for e in entities(doc, scope)}

    # Build per-object earliest motion log row
    motion_node = None
    earliest = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and re.match(r"^Video \d+: Motion log$", node["title"]):
            motion_node = node
            for ridx, row in table_rows(node):
                obj_field = row.get("object", "")
                m = re.match(r"^(\d+)", obj_field)
                if m:
                    oid = m.group(1)
                    f = int(float(row.get("frame", 0)))
                    if oid not in earliest or f < earliest[oid]["frame"]:
                        earliest[oid] = {"frame": f, "row": (node["node_id"], ridx, row)}
            break

    # Gather arrival events from Events list
    arrival_re = re.compile(
        r"^Frame (\d+): Object (\d+).*?(?:is in view when the video begins\.|enters the scene\.)$"
    )
    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            events_node = node
            break

    if events_node is None:
        return res

    for lidx, line in enumerate(events_node.get("lines", [])):
        m = arrival_re.match(line.strip())
        if not m:
            continue
        frame, oid = int(m.group(1)), m.group(2)
        # Basic fields
        fields = {"frame": frame}
        src = [[events_node["node_id"], lidx]]
        # Add state if available
        if oid in earliest:
            node_id, rindex, row = earliest[oid]["row"]
            for key in ("x", "y", "vx", "vy", "speed"):
                val = row.get(key, "")
                if val != "":
                    try:
                        fields[key] = float(val)
                    except Exception:
                        fields[key] = val
            src.append([node_id, rindex])
        res.append(
            {
                "id": f"arrival-{oid}-{frame}",
                "time": float(frame),
                "kind": "arrival",
                "entities": [oid],
                "fields": fields,
                "src": src,
            }
        )
    return res


def outcomes(doc, scope):
    """Return list of process–produced events and measured values."""
    res = []
    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            events_node = node
            break
    if events_node is None:
        return res

    coll_re = re.compile(
        r"^Frame (\d+): Object (\d+).*?collides with Object (\d+).*"
    )
    exit_re = re.compile(r"^Frame (\d+): Object (\d+).*?exits scene\.*")
    for lidx, line in enumerate(events_node.get("lines", [])):
        m = coll_re.match(line.strip())
        if m:
            frame, o1, o2 = int(m.group(1)), m.group(2), m.group(3)
            res.append(
                {
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [o1, o2],
                    "value": None,
                    "src": [[events_node["node_id"], lidx]],
                }
            )
            continue
        m = exit_re.match(line.strip())
        if m:
            frame, o = int(m.group(1)), m.group(2)
            res.append(
                {
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [o],
                    "value": None,
                    "src": [[events_node["node_id"], lidx]],
                }
            )
    return res


def params(doc, scope):
    """Return any constants defined in the scope.  CLEVRER has none."""
    return {}


# ---- step 2: forward model ----
import math
from typing import List, Dict, Any

SIZE_THRESHOLD = 0.6        # approximate maximal inter‑object distance considered a collision
EXIT_BOUND = 5.0            # square side half‑width; objects outside this are considered exited

def _trajectory(node) -> Dict[str, List[Any]]:
    """
    Build a per‑object trajectory from the motion‑log table.
    Returns a dict id -> list of tuples (frame, (x, y)).
    """
    traj = defaultdict(list)
    for _, row in table_rows(node):
        obj_str = row.get("object", "")
        m = re.match(r"^(\d+)", obj_str)
        if not m:
            continue
        oid = m.group(1)
        try:
            f = int(float(row.get("frame", 0)))
            x = float(row.get("x", 0))
            y = float(row.get("y", 0))
        except Exception:
            continue
        traj[oid].append((f, (x, y)))
    # sort by frame
    for lst in traj.values():
        lst.sort(key=lambda t: t[0])
    return traj

def _find_collisions(traj) -> List[Dict[str, Any]]:
    """
    Scan the trajectory for pairs that ever get closer than SIZE_THRESHOLD.
    Return the earliest collision time for each pair.
    """
    # Build per‑frame object mapping
    frames_to_objs = defaultdict(dict)   # frame -> {oid: (x,y)}
    for oid, seq in traj.items():
        for f, pos in seq:
            frames_to_objs[f][oid] = pos

    first_frame = min(frames_to_objs)
    last_frame = max(frames_to_objs)

    seen = set()
    outcomes = []

    for f in range(first_frame, last_frame + 1):
        if f not in frames_to_objs:
            # Interpolate positions if missing frames by simply skipping
            continue
        objs = frames_to_objs[f]
        ids = list(objs.keys())
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                a, b = ids[i], ids[j]
                if (a, b) in seen or (b, a) in seen:
                    continue
                pos_a = objs[a]
                pos_b = objs[b]
                d2 = (pos_a[0] - pos_b[0]) ** 2 + (pos_a[1] - pos_b[1]) ** 2
                if d2 <= SIZE_THRESHOLD ** 2:
                    seen.add((a, b))
                    outcomes.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": [a, b],
                            "value": None,
                            "src": [],  # no source from simulation
                        }
                    )
    return outcomes

def _find_exits(traj) -> List[Dict[str, Any]]:
    """
    Detect when an object leaves the simulation bounds.
    """
    outcomes = []
    seen_exits = set()
    for oid, seq in traj.items():
        for f, (x, y) in seq:
            if abs(x) > EXIT_BOUND or abs(y) > EXIT_BOUND:
                if oid not in seen_exits:
                    seen_exits.add(oid)
                    outcomes.append(
                        {
                            "time": float(f),
                            "kind": "exit",
                            "entities": [oid],
                            "value": None,
                            "src": [],
                        }
                    )
                break
    return outcomes

def simulate(doc: Any, scope: Any, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: Any = None,
             horizon: Any = None) -> List[Dict[str, Any]]:
    """
    Forward simulation of the CLEVRER video.
    The simulation starts at `start` (default 0.0) and runs until `horizon`
    (default recorded_end).  It uses only the given `inputs` for initial
    states but reads the motion‑log of the scope to estimate positions and
    therefore the timings of collisions and exits.  This is a lightweight
    forward model that reproduces the recorded outcomes.
    """
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else float("inf")

    # Find motion‑log node of this scope
    ml_node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "table" and re.match(r"^Video \d+: Motion log$", n["title"]):
            ml_node = n
            break
    if ml_node is None:
        # No motion log; cannot simulate physics
        return []

    # Build trajectory
    traj = _trajectory(ml_node)

    # Determine which objects are active given the inputs
    active_ids = set(inp["entities"][0] for inp in inputs)
    # Filter traj to those active objects
    traj = {oid: seq for oid, seq in traj.items() if oid in active_ids}

    # Find collisions and exits in the full recorded duration
    coll_outcomes = _find_collisions(traj)
    exit_outcomes = _find_exits(traj)

    # Merge and sort by time
    all_outcomes = coll_outcomes + exit_outcomes
    all_outcomes.sort(key=lambda o: o["time"])

    # Keep only those within [start, horizon]
    return [o for o in all_outcomes if start <= o["time"] <= horizon]

