import math
from typing import List, Dict, Any, Tuple
from collections import defaultdict

# ------------------------------------------------------------------
# Helper functions for vector math
# ------------------------------------------------------------------
def _vec_add(a: Tuple[float, float], b: Tuple[float, float]) -> Tuple[float, float]:
    return (a[0] + b[0], a[1] + b[1])

def _vec_mul(a: Tuple[float, float], s: float) -> Tuple[float, float]:
    return (a[0] * s, a[1] * s)

def _dist_sq(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

# threshold for collision detection: usually 2*SIZE where SIZE≈0.25
COLLISION_MAX_DIST_SQ = 0.6 ** 2
EXIT_BOUNDS = 5.0  # objects leave when |x| or |y| > 5

# ------------------------------------------------------------------
# Physics helpers
# ------------------------------------------------------------------
def _collision_time(pos1, vel1, pos2, vel2, cur_time):
    """
    Compute the earliest time >= cur_time at which the distance between
    two objects becomes <= COLLISION_MAX_DIST_SQ.
    """
    r = (pos2[0] - pos1[0], pos2[1] - pos1[1])
    v = (vel2[0] - vel1[0], vel2[1] - vel1[1])
    a = v[0] * v[0] + v[1] * v[1]
    b = 2 * (r[0] * v[0] + r[1] * v[1])
    c = r[0] * r[0] + r[1] * r[1] - COLLISION_MAX_DIST_SQ
    if a == 0:
        # Relative movement is zero
        return cur_time if c <= 0 else None
    discrim = b * b - 4 * a * c
    if discrim < 0:
        return None
    sqrt_disc = math.sqrt(discrim)
    t1 = (-b - sqrt_disc) / (2 * a)
    t2 = (-b + sqrt_disc) / (2 * a)
    cand = [t for t in (t1, t2) if t >= cur_time]
    return min(cand) if cand else None

def _exit_time(pos, vel, cur_time):
    """
    Compute the earliest time at which an object's coordinate crosses
    the EXIT_BOUNDS boundary.
    """
    times = []
    if vel[0] > 0:
        t = (EXIT_BOUNDS - pos[0]) / vel[0]
        if t >= 0: times.append(t)
    elif vel[0] < 0:
        t = (-EXIT_BOUNDS - pos[0]) / vel[0]
        if t >= 0: times.append(t)
    if vel[1] > 0:
        t = (EXIT_BOUNDS - pos[1]) / vel[1]
        if t >= 0: times.append(t)
    elif vel[1] < 0:
        t = (-EXIT_BOUNDS - pos[1]) / vel[1]
        if t >= 0: times.append(t)
    return cur_time + min(times) if times else None

# ------------------------------------------------------------------
# Main simulate function
# ------------------------------------------------------------------
def simulate(doc: Any, scope: Any, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: Any = None,
             horizon: Any = None) -> List[Dict[str, Any]]:
    """
    Forward simulation that respects the initial arrival records
    supplied in `inputs`.  The function ignores all other parts of
    the document except for the optional `recorded_end` value.
    """
    # ------------------------------------------------------------------
    # 1. Build arrival schedule and initial state
    # ------------------------------------------------------------------
    arrivals_by_t: Dict[float, List[Dict[str, Any]]] = defaultdict(list)
    for inp in inputs:
        arrivals_by_t.setdefault(inp["time"], []).append(inp)

    # Determine simulation bounds
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else float("inf")

    # Current state: id -> {'pos': (x,y), 'vel': (vx,vy)}
    state: Dict[str, Dict[str, Tuple[float, float]]] = {}

    # Apply all arrivals at or before start to initialise the state
    for t in sorted(arrivals_by_t):
        if t <= start:
            for arr in arrivals_by_t[t]:
                ent = arr["entities"][0]
                pos = (float(arr["fields"].get("x", 0.0)),
                       float(arr["fields"].get("y", 0.0)))
                vel = (float(arr["fields"].get("vx", 0.0)),
                       float(arr["fields"].get("vy", 0.0)))
                state[ent] = {"pos": pos, "vel": vel}
        else:
            continue

    # Start simulation clock
    cur_time = start

    outcomes: List[Dict[str, Any]] = []

    # ------------------------------------------------------------------
    # 2. Simulation loop
    # ------------------------------------------------------------------
    while cur_time < horizon:
        # Next event time init
        next_t = horizon

        # Upcoming arrivals > cur_time
        future_arrivals = [t for t in arrivals_by_t if t > cur_time]
        if future_arrivals:
            next_t = min(next_t, min(future_arrivals))

        # Collision predictions among current active objects
        eids = list(state.keys())
        for i in range(len(eids)):
            for j in range(i + 1, len(eids)):
                id1, id2 = eids[i], eids[j]
                s1, s2 = state[id1], state[id2]
                t_col = _collision_time(s1["pos"], s1["vel"],
                                        s2["pos"], s2["vel"],
                                        cur_time)
                if t_col is not None and t_col <= next_t:
                    next_t = t_col

        # Exit predictions
        for eid, ent in state.items():
            t_exit = _exit_time(ent["pos"], ent["vel"], cur_time)
            if t_exit is not None and t_exit <= next_t:
                next_t = t_exit

        # If no event before horizon, break
        if next_t >= horizon or next_t == cur_time:
            break

        # Advance all objects to next_t
        dt = next_t - cur_time
        for ent in state.values():
            ent["pos"] = _vec_add(ent["pos"], _vec_mul(ent["vel"], dt))

        cur_time = next_t

        # Process arrivals at this time
        if cur_time in arrivals_by_t:
            for arr in arrivals_by_t[cur_time]:
                ent_id = arr["entities"][0]
                pos = (float(arr["fields"].get("x", 0.0)),
                       float(arr["fields"].get("y", 0.0)))
                vel = (float(arr["fields"].get("vx", 0.0)),
                       float(arr["fields"].get("vy", 0.0)))
                state[ent_id] = {"pos": pos, "vel": vel}

        # Process collisions or exits
        # Re-calc collision again to identify which objects collide at cur_time
        collided_pairs = []
        for i in range(len(eids)):
            for j in range(i + 1, len(eids)):
                id1, id2 = eids[i], eids[j]
                s1, s2 = state[id1], state[id2]
                # Using already advanced positions we check if distance <= cutoff
                if _dist_sq(s1["pos"], s2["pos"]) <= COLLISION_MAX_DIST_SQ:
                    collided_pairs.append((id1, id2))

        # Handle collisions
        for id1, id2 in collided_pairs:
            # Exchange velocities
            state[id1]["vel"], state[id2]["vel"] = state[id2]["vel"], state[id1]["vel"]
            outcomes.append(
                {
                    "time": cur_time,
                    "kind": "collision",
                    "entities": [id1, id2],
                    "value": None,
                    "src": []
                }
            )
            # Remove after processing to avoid double handling
        # After collisions, remove exited objects
        exited = []
        for eid, ent in list(state.items()):
            if abs(ent["pos"][0]) > EXIT_BOUNDS or abs(ent["pos"][1]) > EXIT_BOUNDS:
                outcomes.append(
                    {
                        "time": cur_time,
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    }
                )
                exited.append(eid)
        for eid in exited:
            del state[eid]

    # Filter outcomes to after the given start (for safety)
    final_outcomes = [o for o in outcomes if o["time"] >= start and o["time"] <= horizon]
    return final_outcomes

