EXIT_BOUND = 5.0                           # square half‑width
DT = 0.01                                  # integration step (frames)

# ----------------------------------------------------------------------
# Main forward simulation
# ----------------------------------------------------------------------
def simulate(doc: Any, scope: Any, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: Any = None,
             horizon: Any = None) -> List[Dict[str, Any]]:
    """
    Forward simulation for CLEVRER videos.

    All new state is derived from the explicit 'inputs' list.
    The history of recorded outcomes is ignored; we only use it for the
    `recorded_end` boundary.
    """
    # --- 1. Prepare arrival schedule -------------------------------------------------
    arrivals: Dict[float, List[Dict[str, Any]]] = defaultdict(list)
    for inp in inputs:
        arrivals.setdefault(float(inp["time"]), []).append(inp)

    # --- 2. Get simulation limits ----------------------------------------------------
    recorded_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end if recorded_end is not None else float("inf")

    # --- 3. Initial state -------------------------------------------------------------
    cur_time = start
    state: Dict[str, Dict[str, Tuple[float, float]]] = {}   # id -> {'pos':(x,y), 'vel':(vx,vy)}
    for arr in inputs:
        if float(arr["time"]) <= start:
            ent_id = arr["entities"][0]
            pos = (float(arr["fields"].get("x", 0.0)),
                   float(arr["fields"].get("y", 0.0)))
            vel = (float(arr["fields"].get("vx", 0.0)),
                   float(arr["fields"].get("vy", 0.0)))
            state[ent_id] = {"pos": pos, "vel": vel}

    # Track which unordered pairs have already collided
    collided: set[Tuple[str, str]] = set()

    outcomes: List[Dict[str, Any]] = []

    # ------------------------------------------------------------------
    # 4. Simulation loop – discrete time stepping
    # ------------------------------------------------------------------
    while cur_time < horizon:
        # Determine next immediate arrival (if any) that lies within this step
        next_arrival_time = None
        for t in arrivals:
            if cur_time < t <= cur_time + DT:
                next_arrival_time = t
                break
        if next_arrival_time is None:
            step = DT
            substeps = [(step, None)]   # (duration, arrival_at_this_substep)
        else:
            # split the dt at arrival time
            step1 = next_arrival_time - cur_time
            step2 = DT - step1
            substeps = [(step1, next_arrival_time), (step2, None)]

        for seg_dur, seg_arr_time in substeps:
            # Advance all objects
            for ent in state.values():
                ent["pos"] = _vec_add(ent["pos"], _vec_mul(ent["vel"], seg_dur))

            cur_time += seg_dur

            # If an arrival happens exactly now, add the new entity
            if seg_arr_time is not None:
                for arr in arrivals.get(seg_arr_time, []):
                    eid = arr["entities"][0]
                    pos = (float(arr["fields"].get("x", 0.0)),
                           float(arr["fields"].get("y", 0.0)))
                    vel = (float(arr["fields"].get("vx", 0.0)),
                           float(arr["fields"].get("vy", 0.0)))
                    state[eid] = {"pos": pos, "vel": vel}

            # ------------------------------------------------------------------
            # Detect collisions
            # ------------------------------------------------------------------
            ids = list(state.keys())
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    id1, id2 = ids[i], ids[j]
                    # normalize pair key
                    pair = tuple(sorted((id1, id2)))
                    if pair in collided:
                        continue
                    p1 = state[id1]["pos"]
                    p2 = state[id2]["pos"]
                    if _dist_sq(p1, p2) <= COLLISION_MAX_DIST_SQ:
                        # Record collision
                        outcomes.append(
                            {
                                "time": cur_time,
                                "kind": "collision",
                                "entities": [id1, id2],
                                "value": None,
                                "src": []
                            }
                        )
                        collided.add(pair)
                        # Simple elastic exchange of velocities
                        w1, w2 = state[id1]["vel"], state[id2]["vel"]
                        state[id1]["vel"], state[id2]["vel"] = w2, w1

            # ------------------------------------------------------------------
            # Detect exits
            # ------------------------------------------------------------------
            to_remove = []
            for eid, ent in state.items():
                if abs(ent["pos"][0]) > EXIT_BOUND or abs(ent["pos"][1]) > EXIT_BOUND:
                    outcomes.append(
                        {
                            "time": cur_time,
                            "kind": "exit",
                            "entities": [eid],
                            "value": None,
                            "src": []
                        }
                    )
                    to_remove.append(eid)
            for eid in to_remove:
                del state[eid]

        # Safety stop if we have stepped beyond horizon
        if cur_time >= horizon:
            break

    # Filter out any outcomes that happened before the requested start
    final_outcomes = [o for o in outcomes if o["time"] >= start and o["time"] <= horizon]
    # Sort by time (and by kind to keep stable ordering)
    final_outcomes.sort(key=lambda o: (o["time"], o["kind"]))
    return final_outcomes

import re
from collections import defaultdict

# Helpers: node_by_title, node_by_id, children, scope_nodes, table_rows
# are assumed provided in the evaluation environment.

def entities(doc, scope):
    """Return a list of entity dicts for the scope."""
    ents = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Objects$", node["title"]):
            for line in node.get("lines", []):
                m = re.match(r"^Object (\d+): (.+?) \((?:color=[^,]+, material=[^,]+, shape=[^)]+)\)$",
                             line.strip())
                if m:
                    oid, desc = m.group(1), m.group(2).strip()
                    ents.append({"id": oid, "description": desc})
    return ents


def recorded_end(doc, scope):
    """Return last frame number seen in the scope."""
    last = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and re.match(r"^Video \d+: Motion log$", node["title"]):
            for idx, row in table_rows(node):
                try:
                    f = int(float(row.get("frame", 0)))
                    if last is None or f > last:
                        last = f
                except Exception:
                    continue
        elif node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            for line in node.get("lines", []):
                m = re.match(r"^Frame (\d+):", line.strip())
                if m:
                    f = int(m.group(1))
                    if last is None or f > last:
                        last = f
    return float(last) if last is not None else None


def inputs(doc, scope):
    """Return list of external input records."""
    res = []
    # Map of id -> description
    ent_map = {e["id"]: e["description"] for e in entities(doc, scope)}

    # Build per-object earliest motion log row
    motion_node = None
    earliest = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and re.match(r"^Video \d+: Motion log$", node["title"]):
            motion_node = node
            for ridx, row in table_rows(node):
                obj_field = row.get("object", "")
                m = re.match(r"^(\d+)", obj_field)
                if m:
                    oid = m.group(1)
                    f = int(float(row.get("frame", 0)))
                    if oid not in earliest or f < earliest[oid]["frame"]:
                        earliest[oid] = {"frame": f, "row": (node["node_id"], ridx, row)}
            break

    # Gather arrival events from Events list
    arrival_re = re.compile(
        r"^Frame (\d+): Object (\d+).*?(?:is in view when the video begins\.|enters the scene\.)$"
    )
    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            events_node = node
            break

    if events_node is None:
        return res

    for lidx, line in enumerate(events_node.get("lines", [])):
        m = arrival_re.match(line.strip())
        if not m:
            continue
        frame, oid = int(m.group(1)), m.group(2)
        # Basic fields
        fields = {"frame": frame}
        src = [[events_node["node_id"], lidx]]
        # Add state if available
        if oid in earliest:
            node_id, rindex, row = earliest[oid]["row"]
            for key in ("x", "y", "vx", "vy", "speed"):
                val = row.get(key, "")
                if val != "":
                    try:
                        fields[key] = float(val)
                    except Exception:
                        fields[key] = val
            src.append([node_id, rindex])
        res.append(
            {
                "id": f"arrival-{oid}-{frame}",
                "time": float(frame),
                "kind": "arrival",
                "entities": [oid],
                "fields": fields,
                "src": src,
            }
        )
    return res


def outcomes(doc, scope):
    """Return list of process–produced events and measured values."""
    res = []
    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and re.match(r"^Video \d+: Events$", node["title"]):
            events_node = node
            break
    if events_node is None:
        return res

    coll_re = re.compile(
        r"^Frame (\d+): Object (\d+).*?collides with Object (\d+).*"
    )
    exit_re = re.compile(r"^Frame (\d+): Object (\d+).*?exits scene\.*")
    for lidx, line in enumerate(events_node.get("lines", [])):
        m = coll_re.match(line.strip())
        if m:
            frame, o1, o2 = int(m.group(1)), m.group(2), m.group(3)
            res.append(
                {
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [o1, o2],
                    "value": None,
                    "src": [[events_node["node_id"], lidx]],
                }
            )
            continue
        m = exit_re.match(line.strip())
        if m:
            frame, o = int(m.group(1)), m.group(2)
            res.append(
                {
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [o],
                    "value": None,
                    "src": [[events_node["node_id"], lidx]],
                }
            )
    return res


def params(doc, scope):
    """Return any constants defined in the scope.  CLEVRER has none."""
    return {}


