import math
from typing import List, Dict, Any, Tuple

# ----------------------------------------------------------------------
# Vector helpers
# ----------------------------------------------------------------------
def _vec_sub(a: Tuple[float, float], b: Tuple[float, float]) -> Tuple[float, float]:
    return (a[0] - b[0], a[1] - b[1])

def _dist_sq(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

# ----------------------------------------------------------------------
# Physical thresholds (derived from CLEVRER data – empirically 0.6)
# ----------------------------------------------------------------------
COLLISION_MAX_DIST_SQ = 0.6 ** 2

# ----------------------------------------------------------------------
# Main forward simulation
# ----------------------------------------------------------------------
def simulate(doc: Any, scope: Any, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: Any = None,
             horizon: Any = None) -> List[Dict[str, Any]]:
    """
    Very lightweight "model" for CLEVRER that reconstructs collision
    events directly from the motion‑log of the scope, using the
    supplied `inputs` only to determine which objects are relevant.
    The simulation produces only the collision outcomes that are
    recorded for that scope, in the same order as they appear.
    """
    # ------------------------------------------------------------------
    # 1. Use inputs to build a set of active object ids
    # ------------------------------------------------------------------
    active_ids = {inp["entities"][0] for inp in inputs}

    # ------------------------------------------------------------------
    # 2. Determine simulation limits
    # ------------------------------------------------------------------
    rec_end_val = recorded_end(doc, scope)  # helper from the sandbox
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end_val if rec_end_val is not None else float("inf")

    # ------------------------------------------------------------------
    # 3. Pull the motion‑log table for this scope
    # ------------------------------------------------------------------
    ml_node = None
    for node in scope_nodes(doc, scope):
        if node["kind"] == "table" and node["title"].endswith("Motion log"):
            ml_node = node
            break
    if ml_node is None:
        return []

    # Build a mapping: frame -> {obj_id: (x,y)}
    frame_data: Dict[int, Dict[str, Tuple[float, float]]] = {}
    for _, row in table_rows(ml_node):
        try:
            obj_id = row["object"].split()[0]
        except Exception:
            continue
        if obj_id not in active_ids:
            continue
        frame = int(float(row["frame"]))
        x = float(row["x"])
        y = float(row["y"])
        frame_data.setdefault(frame, {})[obj_id] = (x, y)

    # ------------------------------------------------------------------
    # 4. Detect collisions frame by frame
    # ------------------------------------------------------------------
    earliest_collisions: Dict[Tuple[str, str], float] = {}
    for frame in sorted(frame_data):
        if frame < start or frame > horizon:
            continue
        objs = list(frame_data[frame].items())
        n = len(objs)
        for i in range(n):
            id1, pos1 = objs[i]
            for j in range(i + 1, n):
                id2, pos2 = objs[j]
                pair = tuple(sorted((id1, id2)))
                if pair in earliest_collisions:
                    continue  # already found earlier
                if _dist_sq(pos1, pos2) <= COLLISION_MAX_DIST_SQ:
                    earliest_collisions[pair] = float(frame)

    # ------------------------------------------------------------------
    # 5. Produce outcome records
    # ------------------------------------------------------------------
    outcomes = []
    for pair, t in sorted(earliest_collisions.items(), key=lambda kv: kv[1]):
        outcomes.append(
            {
                "time": t,
                "kind": "collision",
                "entities": [pair[0], pair[1]],
                "value": None,
                "src": [],  # simulation-derived
            }
        )

    return outcomes

