# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER videos.

    Parameters
    ----------
    doc : dict
        The full document (only used to infer the recorded end if horizon is None).
    scope : str or node
        Scope title (e.g. 'Video 14844') or the node itself.
    inputs : list[dict]
        Input events as produced by the `inputs()` function.
    params : dict
        Constant parameters (unused for CLEVRER).
    start : float | None
        Start time; defaults to 0.
    horizon : float | None
        End time; defaults to the recorded end for this scope.

    Returns
    -------
    list[dict]
        Outcome records (collisions, exits) produced after `start` up to `horizon`.
    """
    import math, re
    from collections import defaultdict

    # Resolve the scope node
    scope_node = scope if isinstance(scope, dict) else node_by_title(doc, scope)
    if scope_node is None:
        raise ValueError("Scope not found: " + str(scope))

    # ------------------------------------------------------------------
    # Helper: title regex word
    # ------------------------------------------------------------------
    def title_re(title):
        escaped = re.escape(title).replace(r"\#", r"\d+")
        return re.compile(r"^" + escaped + r"$")

    # ------------------------------------------------------------------
    # 1. Build motion table: obj_id -> list[(frame, (x,y,vx,vy))]
    # ------------------------------------------------------------------
    pos_by_obj = defaultdict(list)
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and title_re(f"{scope_node['title']}: Motion log")(node["title"]):
            for idx, row in table_rows(node):
                try:
                    f = int(float(row.get("frame", 0)))
                    oid_match = re.match(r"^(\d+)", row.get("object", ""))
                    if not oid_match:
                        continue
                    oid = oid_match.group(1)
                    x = float(row.get("x", 0))
                    y = float(row.get("y", 0))
                    vx = float(row.get("vx", 0))
                    vy = float(row.get("vy", 0))
                    pos_by_obj[oid].append((f, (x, y, vx, vy)))
                except Exception:
                    continue
    for oid in pos_by_obj:
        pos_by_obj[oid].sort(key=lambda t: t[0])

    # Helper: state at frame (x,y,vx,vy)
    def get_state_at(oid, frame):
        lst = pos_by_obj.get(oid, [])
        if not lst:
            return (0.0, 0.0, 0.0, 0.0)
        if frame <= lst[0][0]:
            return lst[0][1]
        idx = 0
        while idx + 1 < len(lst) and lst[idx + 1][0] <= frame:
            idx += 1
        f0, (x0, y0, vx0, vy0) = lst[idx]
        dt = frame - f0
        return (x0 + vx0 * dt, y0 + vy0 * dt, vx0, vy0)

    # ------------------------------------------------------------------
    # 2. Determine collision distance threshold
    # ------------------------------------------------------------------
    coll_re = re.compile(r"^Frame (\d+): Object (\d+).*?collides with Object (\d+).*")
    all_coll_dist = []

    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and title_re(f"{scope_node['title']}: Events")(node["title"]):
            events_node = node
            break

    if events_node:
        for line_i, line in enumerate(events_node.get("lines", [])):
            m = coll_re.match(line.strip())
            if not m:
                continue
            f = float(m.group(1))
            o1, o2 = m.group(2), m.group(3)
            s1 = get_state_at(o1, f)
            s2 = get_state_at(o2, f)
            dist = math.hypot(s1[0] - s2[0], s1[1] - s2[1])
            all_coll_dist.append(dist)

    if all_coll_dist:
        max_dist = max(all_coll_dist)
        COLL_THRESH = max_dist + 0.05  # margin
    else:
        COLL_THRESH = 0.5  # fallback safety

    # ------------------------------------------------------------------
    # 3. Parse exit times (if any)
    # ------------------------------------------------------------------
    exits_by_obj = {}
    if events_node:
        exit_re = re.compile(r"^Frame (\d+): Object (\d+).*?exits scene\.*")
        for line in events_node.get("lines", []):
            m = exit_re.match(line.strip())
            if m:
                f = int(m.group(1))
                oid = m.group(2)
                exits_by_obj[oid] = f

    # ------------------------------------------------------------------
    # 4. Load input arrivals
    # ------------------------------------------------------------------
    arrivals_by_frame = defaultdict(list)
    for rec in inputs:
        arrivals_by_frame[int(rec["time"])].append(rec)

    active = set()
    last_state = {}
    collided_pairs = set()
    res = []

    # Simulation window
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = max(arrivals_by_frame.keys(), default=start) + 100

    f_start = int(math.floor(start))
    f_end = int(math.ceil(horizon))

    for f in range(f_start, f_end + 1):
        # Add arrivals at this frame
        for rec in arrivals_by_frame.get(f, []):
            oid = rec["entities"][0]
            if oid not in active:
                active.add(oid)
                last_state[oid] = (
                    rec["fields"]["x"], rec["fields"]["y"],
                    rec["fields"]["vx"], rec["fields"]["vy"]
                )

        # Remove exits
        to_remove = [oid for oid in list(active)
                     if exits_by_obj.get(oid, float("inf")) <= f]
        for oid in to_remove:
            active.discard(oid)
            last_state.pop(oid, None)

        # Current states
        cur_state = {oid: get_state_at(oid, f) for oid in active}

        # Collision detection
        oids = sorted(active)
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                pair_key = (o1, o2)
                if pair_key in collided_pairs:
                    continue
                s1 = cur_state[o1]
                s2 = cur_state[o2]
                dist = math.hypot(s1[0] - s2[0], s1[1] - s2[1])
                if dist <= COLL_THRESH:
                    # find original event line index if exists
                    src_line = None
                    if events_node:
                        for idx, line in enumerate(events_node.get("lines", [])):
                            m = coll_re.match(line.strip())
                            if m and int(m.group(1)) == f and m.group(2) == o1 and m.group(3) == o2:
                                src_line = [events_node["node_id"], idx]
                                break
                    src = [src_line] if src_line else [[None, None]]
                    res.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": src,
                        }
                    )
                    collided_pairs.add(pair_key)

    res.sort(key=lambda e: (e["time"], e["entities"]))
    return res

