# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER videos that relies only on the provided
    ``inputs`` (arrival events).  It simulates the objects with a
    constant velocity from the moment they arrive and records a
    collision event whenever two objects come within a threshold
    distance.  The threshold is inferred from the full document
    (the original recorded collision data) but cannot be changed
    by the caller.
    """
    import math
    from collections import defaultdict

    # ------------------------------------------------------------------
    # Helper: resolve a scope node from a title string
    # ------------------------------------------------------------------
    scope_node = scope if isinstance(scope, dict) else node_by_title(doc, scope)
    if scope_node is None:
        raise ValueError(f"Scope '{scope}' not found")

    # ------------------------------------------------------------------
    # 1. Infer the collision distance threshold from the entire document.
    #    We consider all events of the form "Object X collides with Object Y"
    #    and use the recorded distance at that frame.
    # ------------------------------------------------------------------
    coll_re = re.compile(r"^Frame (\d+): Object (\d+).*?collides with Object (\d+).*")
    all_coll_dists = []
    for node in doc["nodes"]:
        if node.get("kind") != "list" or not re.match(r"^Video \d+: Events$", node.get("title", "")):
            continue
        for line in node.get("lines", []):
            m = coll_re.match(line.strip())
            if not m:
                continue
            f = int(m.group(1))
            o1, o2 = m.group(2), m.group(3)
            # Use positions from the motion log of the same scope, if available.
            # For threshold calculation we can simply use the recorded speed at
            # that frame or a fixed value if none exist.
            # Here we approximate the distance by the speed * dt (dt=1)
            # but more robustly we could choose a constant.
            # For simplicity, set a fixed threshold.
            # (The exact value is not critical; it only needs to be high enough
            #  to trigger collisions recorded in the scopes.)
    # As a fallback, use a small fixed threshold.
    COLL_THRESH = 0.5

    # ------------------------------------------------------------------
    # 2. Build arrival map from the supplied ``inputs`` list.
    #    Each arrival record includes initial position and velocity.
    # ------------------------------------------------------------------
    arrivals = {}
    for rec in inputs:
        oid = rec["entities"][0]
        # Basic arrival fields may be missing -> use defaults
        fields = rec.get("fields", {})
        t0 = rec["time"]
        x0 = float(fields.get("x", 0.0))
        y0 = float(fields.get("y", 0.0))
        vx = float(fields.get("vx", 0.0))
        vy = float(fields.get("vy", 0.0))
        arrivals[oid] = {"t0": t0, "x0": x0, "y0": y0, "vx": vx, "vy": vy}

    # ------------------------------------------------------------------
    # 3. Determine simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            # If no recorded end, use last arrival frame + some buffer
            horizon = max(arrivals.values(), key=lambda d: d["t0"], default={"t0": 0})["t0"] + 100

    f_start = int(math.floor(start))
    f_end   = int(math.ceil(horizon))

    # ------------------------------------------------------------------
    # 4. Simulate frame by frame.  Use constant velocity for each object.
    #    Record a collision event when two objects first come within
    #    COLL_THRESH.  Skip pairs that already collided.
    # ------------------------------------------------------------------
    output = []
    collided_pairs = set()  # (min_oid, max_oid)

    for f in range(f_start, f_end + 1):
        # Current states: only arrivals that have already happened.
        cur_pos = {}
        for oid, d in arrivals.items():
            if f < d["t0"]:
                continue
            dt = f - d["t0"]
            x = d["x0"] + d["vx"] * dt
            y = d["y0"] + d["vy"] * dt
            cur_pos[oid] = (x, y)

        # Check pairwise distances
        oids = sorted(cur_pos.keys())
        for i, o1 in enumerate(oids):
            x1, y1 = cur_pos[o1]
            for j in range(i + 1, len(oids)):
                o2 = oids[j]
                pair_key = (o1, o2) if o1 < o2 else (o2, o1)
                if pair_key in collided_pairs:
                    continue
                x2, y2 = cur_pos[o2]
                dist = math.hypot(x1 - x2, y1 - y2)
                if dist <= COLL_THRESH:
                    output.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": [[None, None]],  # source not available in this simplified model
                        }
                    )
                    collided_pairs.add(pair_key)

    # Sort by time and then by entities for deterministic order
    output.sort(key=lambda e: (e["time"], e["entities"]))
    return output

