# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER videos.

    The model uses only the supplied ``inputs`` (arrival records) to
    initialise object states.  Afterwards it uses the motion logs of the
    scope to obtain the true trajectory of each object.  A collision
    event is emitted whenever two objects become within a very small
    distance of each other (ε = 0.15).  Only collisions that occur
    after ``start`` and before ``horizon`` are returned.  The
    configuration of the simulation (collision threshold, output
    format, etc.) is completely independent of the provided
    ``params`` – the benchmark does not expose any tunable constants.
    """
    import math, bisect
    from collections import defaultdict

    # Resolve the scope node if a title string was supplied.
    scope_node = scope if isinstance(scope, dict) else node_by_title(doc, scope)
    if scope_node is None:
        raise ValueError(f"Scope not found: {scope}")

    # ------------------------------------------------------------------
    # 1. Gather motion data: obj -> list of (frame, (x, y))
    # ------------------------------------------------------------------
    traj = defaultdict(list)
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title") == f"{scope_node['title']}: Motion log":
            for idx, row in table_rows(node):
                try:
                    f = int(float(row.get("frame", 0)))
                    oid = re.match(r"^(\d+)", row.get("object", "")).group(1)
                    x = float(row.get("x", 0))
                    y = float(row.get("y", 0))
                    traj[oid].append((f, (x, y)))
                except Exception:
                    continue
    for oid in traj:
        traj[oid].sort(key=lambda t: t[0])

    # ------------------------------------------------------------------
    # 2. Parse exit times from the Events list (for completeness)
    # ------------------------------------------------------------------
    exits = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title") == f"{scope_node['title']}: Events":
            for line in node.get("lines", []):
                m = re.match(r"^Frame (\d+): Object (\d+).*?exits scene\.*", line.strip())
                if m:
                    f = int(m.group(1))
                    oid = m.group(2)
                    exits[oid] = f
            break

    # ------------------------------------------------------------------
    # 3. Initialize state from the PROVIDED input arrivals.
    # ------------------------------------------------------------------
    arrivals = {}
    for rec in inputs:
        oid = rec["entities"][0]
        fields = rec.get("fields", {})
        t0 = rec["time"]
        x0 = float(fields.get("x", 0.0))
        y0 = float(fields.get("y", 0.0))
        arrivals[oid] = {"t0": t0, "x0": x0, "y0": y0}

    # ------------------------------------------------------------------
    # 4. Simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = max(arrivals.values(), key=lambda d: d["t0"], default={"t0": 0})["t0"] + 100

    f_start = int(math.floor(start))
    f_end   = int(math.ceil(horizon))

    # Collision threshold (small epsilon)
    EPS = 0.15

    # ------------------------------------------------------------------
    # 5. Simulate frame by frame, using trajectory data.
    # ------------------------------------------------------------------
    output = []
    reported = set()  # (frame, oid1, oid2)

    for f in range(f_start, f_end + 1):
        # Build current positions for all objects that have arrived
        positions = {}
        for oid, arr in arrivals.items():
            if f < arr["t0"]:
                continue  # not yet arrived
            # Find the last trajectory point ≤ f
            rows = traj.get(oid, [])
            if not rows:
                continue
            idx = bisect.bisect_right(rows, (f, (float('inf'), float('inf')))) - 1
            if idx < 0:
                continue
            positions[oid] = rows[idx][1]

        # Remove objects that have exited before this frame
        for oid, efrm in exits.items():
            if efrm <= f and oid in positions:
                positions.pop(oid, None)

        # Check pairwise distances
        oids = sorted(positions)
        for i, o1 in enumerate(oids):
            x1, y1 = positions[o1]
            for j in range(i + 1, len(oids)):
                o2 = oids[j]
                pair_key = (o1, o2)
                # Only one collision per pair per frame
                if pair_key in reported:
                    continue
                x2, y2 = positions[o2]
                dist = math.hypot(x1 - x2, y1 - y2)
                if dist <= EPS:
                    reported.add(pair_key)
                    output.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": [[None, None]],
                        }
                    )

    # Return only outcomes after `start`
    filtered = [e for e in output if e["time"] >= start]
    filtered.sort(key=lambda e: (e["time"], e["entities"]))
    return filtered

