# 3️⃣  Verify that colliding objects are within collision distance pre‑collision
from math import hypot
radius = 0.3
tol = 0.05
problematic = []
for node in doc["nodes"]:
    if node.get("kind") != "text" or not re.match(r"^Video \d+$", node["title"]):
        continue
    # get motion log tables
    motion_tables = [cn for cn in [node_by_id(doc, cid) for cid in node.get("children",[])]
                     if cn.get("kind")=="table" and re.match(r"^Video \d+: Motion log$", cn["title"])]
    if not motion_tables:
        continue
    motion_rows = {}
    for mt in motion_tables:
        motion_rows[mt["node_id"]] = {int(r["frame"]): r for _, r in table_rows(mt)}
    events_node = None
    for cn in [node_by_id(doc, cid) for cid in node.get("children",[])]:
        if cn.get("kind")=="list" and cn["title"]==f"{node['title']}: Events":
            events_node = cn
            break
    if not events_node: continue
    coll_re = re.compile(r"^Frame (\d+): Object (\d+).*?collides with Object (\d+).*")
    for line in events_node.get("lines", []):
        m = coll_re.match(line.strip())
        if not m: continue
        frame, o1, o2 = int(m.group(1)), m.group(2), m.group(3)
        # get positions at that frame from motion log
        r1 = None; r2 = None
        for rows in motion_rows.values():
            if r1 is None and frame in rows:
                r1 = rows[frame]
            if r2 is None and frame in rows:
                r2 = rows[frame]
            if r1 and r2:
                break
        if not r1 or not r2: continue
        x1, y1 = float(r1["x"]), float(r1["y"])
        x2, y2 = float(r2["x"]), float(r2["y"])
        dist = hypot(x1-x2, y1-y2)
        if dist > 2*radius+tol:
            problematic.append((node['title'], frame, o1, o2, dist))
print("Situations where recorded colliding objects were far apart at event frame:")
for p in problematic:
    print(p)

